  { destinations: ["buz"], destination: "Búzios, Brasil", title: "Full Day Arraial do Cabo", description: "¡Conoce el Caribe brasileño! Una excursión imperdible desde Búzios para descubrir las aguas cristalinas y las arenas blancas de Arraial do Cabo, incluyendo almuerzo.", price: 53.62, details: "Disfruta de un día de excursión hacia Arraial do Cabo, mundialmente conocido por sus transparentes aguas turquesas y su fina arena blanca. Este tour conecta Búzios con uno de los destinos más bellos del litoral fluminense, permitiéndote disfrutar de paisajes paradisíacos, vistas panorámicas y un delicioso almuerzo buffet libre incluido para recargar energías.", image: "https://hqyzmeordvjccytgltse.supabase.co/storage/v1/object/public/tours/Buzios/arraial%201.webp", duracion: "8 hs", grupo: "Hasta 30 personas", edad: "Desde 3 años", incluye: ["Transporte terrestre ida y vuelta desde Búzios hacia Arraial do Cabo","Acompañamiento de guía especializado","Traslado hacia las zonas de interés","Almuerzo buffet libre"], noIncluye: ["Bebidas","Postres","Tasa portuaria o ambiental de embarque local (si aplica)","Alquiler de equipos de snorkel","Gastos personales"], llevar: ["Traje de baño","Toalla","Ropa cómoda","Protector solar","Gafas de sol","Sombrero o gorra","Dinero o tarjeta para consumos"] },
  { destinations: ["buz"], destination: "Búzios, Brasil", title: "City Tour Rio de Janeiro", description: "¡Disfruta de un día inolvidable en Río de Janeiro! Una excursión completa saliendo desde Búzios para conocer los lugares más emblemáticos de la Ciudad Maravilhosa.", price: 82.8, details: "Una experiencia fantástica de día completo que te permite conectar las playas de Búzios con la inigualable energía, cultura y monumentos históricos de Río de Janeiro. El tour incluye el traslado terrestre de ida y vuelta con guías especializados, ofreciendo un recorrido panorámico por los puntos más famosos de la metrópoli carioca para que disfrutes al máximo de tu visita.", image: "https://hqyzmeordvjccytgltse.supabase.co/storage/v1/object/public/tours/Buzios/city%20tour%20rio%201.webp", duracion: "8 hs", grupo: "Hasta 30 personas", edad: "Sin restricciones", incluye: ["Transporte terrestre ida y vuelta desde Búzios hacia Río de Janeiro","Acompañamiento de guía de turismo acreditado durante el recorrido por los principales atractivos de la ciudad"], noIncluye: ["Almuerzo","Bebidas","Consumos personales","Entradas a atracciones específicas o monumentos que requieran ticket de acceso (según el itinerario contratado)"], llevar: ["Ropa y calzado muy cómodos","Protector solar","Gafas de sol","Sombrero o gorra","Documento de identidad","Cámara o teléfono para fotos"] }
